param([string]$ProjectDirectory=(Split-Path $PSScriptRoot -Parent),[string]$EnvironmentFile="C:\PerformanceTracker\config\.env.production.local",[Parameter(Mandatory=$true)][string]$PublicKeyFile,[Parameter(Mandatory=$true)][string]$OffHostDirectory,[string]$PostgresBinDirectory="",[string]$DailyTime="02:30")
$ErrorActionPreference="Stop";$project=[IO.Path]::GetFullPath($ProjectDirectory);$worker=Join-Path $project "scripts\export-audit-ledger.ps1";if(-not(Test-Path -LiteralPath $worker)){throw "Audit export worker not found"};if(-not(Test-Path -LiteralPath $EnvironmentFile)){throw "Protected production environment file not found"}
$command="`$lines=Get-Content -LiteralPath '$EnvironmentFile';foreach(`$line in `$lines){if(`$line -match '^([A-Z0-9_]+)=(.*)$'){[Environment]::SetEnvironmentVariable(`$matches[1],`$matches[2],'Process')}};& '$worker' -PublicKeyFile '$PublicKeyFile' -OffHostDirectory '$OffHostDirectory'";if($PostgresBinDirectory){$command+=" -PostgresBinDirectory '$PostgresBinDirectory'"};$action=New-ScheduledTaskAction -Execute "powershell.exe" -Argument "-NoProfile -NonInteractive -ExecutionPolicy AllSigned -Command `"$command`"";$trigger=New-ScheduledTaskTrigger -Daily -At $DailyTime;$settings=New-ScheduledTaskSettingsSet -StartWhenAvailable -MultipleInstances IgnoreNew -ExecutionTimeLimit(New-TimeSpan -Minutes 30)
Register-ScheduledTask -TaskName "Performance-Tracker-Audit-Export" -Action $action -Trigger $trigger -Settings $settings -Description "Exports, seals, encrypts, and verifies the off-host Performance Tracker audit ledger" -Force
